def gen(rng):
    chars = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789.,!?-'
    def sentence(n, sp):
        out = []
        for i in range(n):
            if 0 < i < n - 1 and rng.random() < sp:
                out.append(' ')
            else:
                out.append(rng.choice(chars))
        out[0] = rng.choice(chars)
        out[-1] = rng.choice(chars)
        return ''.join(out)
    tests = ['a', 'Hello world', 'a  b   c', 'a b', 'ab', 'a   b', 'Practice makes perfect, every day.', 'x y z w', '1 2 3', 'Hi!  How  are you?']
    for n in (3, 5, 8, 12, 20, 40, 80, 150):
        for _ in range(3):
            tests.append(sentence(n, rng.choice([0.05, 0.2, 0.5, 0.8])))
    n = 100000
    tests.append(sentence(n, 0.15))
    tests.append(sentence(n, 0.6))
    tests.append('a' * n)
    tests.append(' '.join(['a'] * 50000))
    tests.append('a' + ' ' * (n - 2) + 'b')
    return tests

